    "html": "<section class=\"lesson-demo\">\n  <h2>构造函数、实例与返回对象的例外</h2>\n  <p>修改代码并运行，对比输出。</p>\n  <pre id=\"result\" aria-live=\"polite\"></pre>\n</section>",
    "css": "",
    "js": "const output = document.querySelector('#result');\nfunction print(...values) {\n  const text = values\n    .map((value) =>\n      typeof value === 'object' ? JSON.stringify(value, null, 2) : String(value),\n    )\n    .join(' ');\n  output.textContent += text + '\\n';\n  console.log(...values);\n}\nfunction Student(name) {\n  this.name = name;\n}\nStudent.school = '前端实验室';\nStudent.prototype.greet = function () {\n  return '你好，' + this.name;\n};\nconst a = new Student('小林');\nconst b = new Student('小雨');\nprint(a.greet(), b.greet());\nprint('静态：', Student.school, '实例：', a.school);\nfunction Replacement() {\n  this.ignored = true;\n  return { replaced: true };\n}\nprint(new Replacement());",
