    "title": "节点关系、克隆与安全删除",
    "module": "组件交互拆解",
    "what": "parentElement、children与相邻元素用于查找关系。cloneNode复制结构和属性，但不会复制addEventListener注册的事件；克隆后需避免重复id。",
    "subtitle": "parentElement、children与相邻元素用于查找关系。",
    "html": "<section class=\"lesson-demo\">\n  <h2>节点关系、克隆与安全删除</h2>\n  <ul id=\"tree\">\n    <li>\n      第一项\n      <button>删除</button>\n    </li>\n    <li>\n      第二项\n      <button>删除</button>\n    </li>\n  </ul>\n  <button id=\"clone\">克隆第一项</button>\n  <p id=\"info\" role=\"status\"></p>\n</section>",
    "css": "",
    "js": "const tree = document.querySelector('#tree');\nfunction report() {\n  document.querySelector('#info').textContent =\n    'children：' + tree.children.length + '，childNodes：' + tree.childNodes.length;\n}\ndocument.querySelector('#clone').onclick = () => {\n  if (!tree.firstElementChild) return;\n  tree.append(tree.firstElementChild.cloneNode(true));\n  report();\n};\ntree.addEventListener('click', (event) => {\n  if (event.target.closest('button')) {\n    event.target.closest('li').remove();\n    report();\n  }\n});\nreport();",
